def choose_move(observation):
    def is_num(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def is_pos(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1])

    def get_pos(obj):
        if is_pos(obj):
            return [obj[0], obj[1]]
        if isinstance(obj, dict):
            for k in ("position", "pos", "loc", "location", "xy", "coord", "coords"):
                v = obj.get(k)
                if is_pos(v):
                    return [v[0], v[1]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_step(v):
        if v > 1:
            return 1
        if v < -1:
            return -1
        return v

    def add(lst, p):
        if p is not None:
            lst.append(p)

    def collect_positions(x, out):
        if x is None:
            return
        p = get_pos(x)
        if p is not None:
            out.append(p)
            return
        if isinstance(x, dict):
            for k, v in x.items():
                if k in ("grid", "map", "board", "terrain", "walls", "obstacles"):
                    continue
                collect_positions(v, out)
        elif isinstance(x, (list, tuple)):
            for v in x:
                collect_positions(v, out)

    def extract_grid(obs):
        for k in ("grid", "map", "board", "terrain"):
            g = obs.get(k)
            if isinstance(g, (list, tuple)):
                return g
        return None

    def in_bounds(grid, x, y):
        if not grid:
            return True
        h = len(grid)
        if y < 0 or y >= h:
            return False
        row = grid[y]
        if not isinstance(row, (list, tuple)):
            return True
        return 0 <= x < len(row)

    def blocked(grid, x, y):
        if not grid:
            return False
        if not in_bounds(grid, x, y):
            return True
        v = grid[y][x]
        if isinstance(v, str):
            return v in ("#", "X", "x", "W", "w", "A", "a")
        if is_num(v):
            return v in (-1, 9, 99)
        return False

    def safe_targets_from_keys(obs, keys):
        out = []
        for k in keys:
            collect_positions(obs.get(k), out)
        return out

    me = None
    for k in ("position", "pos", "agent_pos", "agent_position", "self", "me", "player"):
        me = get_pos(observation.get(k))
        if me is not None:
            break

    if me is None:
        # fallback: find first position anywhere
        found = []
        collect_positions(observation, found)
        if found:
            me = found[0]
        else:
            return [0, 0]

    grid = extract_grid(observation)

    resources = safe_targets_from_keys(
