    )
    allies = safe_targets_from_keys(observation, ("allies", "ally", "team", "teammates"))
    hazards = safe_targets_from_keys(
        observation,
        ("hazards", "hazard", "traps", "trap", "threats", "threat", "bombs", "bomb")
